const log = find_block({ name: 'oak_log', max_distance: 32 });
if (!log) {
  return { done: false, detail: 'no oak log within 32 blocks' };
}
await dig(log.x, log.y, log.z);
const left = await leave_at_depot('oak_log', 1);
if (!left.ok) {
  return { done: false, detail: left.detail };
}
return { done: true, detail: 'mined an oak log and left it at the depot' };
